                   float routed_scaling_factor, cudaStream_t stream) {
  if (dims.m == 128 && dims.n == 256 && dims.k == 7168 && gemm1_weights.size(0) == 256 && dims.top_k == 8 && dims.block_m == 16) {
    LaunchFusedBatch(hidden_states, hidden_states_scale, gemm1_weights, gemm1_weights_scale,
