        static_cast<uint8_t*>(hidden_states_scale.data_ptr()),
        w1_scale_map,
        static_cast<float*>(output1_scale_gate_scalar.data_ptr()),
        static_cast<float*>(output1_scale_scalar.data_ptr()),
        static_cast<int*>(sorted_token_ids.data_ptr()),
        static_cast<int*>(expert_ids.data_ptr()),
        static_cast<int*>(num_tokens_post_padded.data_ptr()),
        static_cast<uint8_t*>(act_workspace.data_ptr()),
        static_cast<uint8_t*>(sf_workspace.data_ptr()),
        dims.m,
        dims.k,
        dims.top_k,
        dims.block_m);
    CheckCuda(cudaGetLastError(), "alphamoe_nvfp4 up launch");
    CheckCuda(cudaFuncSetAttribute(nvfp4_batch_prepared_g8_down_word::kernel_alpha_moe_nvfp4_down_workspace_nvfp4_batch_prepared_g8_down_word, cudaFuncAttributeMaxDynamicSharedMemorySize,
        nvfp4_batch_prepared_g8_down_word::kGeneratedSmemTotal), "cudaFuncSetAttribute(alphamoe_nvfp4 down)");
    nvfp4_batch_prepared_g8_down_word::kernel_alpha_moe_nvfp4_down_workspace_nvfp4_batch_prepared_g8_down_word<<<down_grid, dim3(nvfp4_batch_prepared_g8_down_word::kGeneratedThreads, 1, 1),
        nvfp4_batch_prepared_g8_down_word::kGeneratedSmemTotal, stream>>>(
        gemm2_map,
        w2_scale_map,
        static_cast<float*>(output2_scale_scalar.data_ptr()),
        static_cast<int*>(sorted_token_ids.data_ptr()),
        static_cast<int*>(expert_ids.data_ptr()),
        static_cast<int*>(num_tokens_post_padded.data_ptr()),
        static_cast<float*>(topk_weights.data_ptr()),
        static_cast<float*>(accumulator.data_ptr()),
        static_cast<uint8_t*>(act_workspace.data_ptr()),
        static_cast<uint8_t*>(sf_workspace.data_ptr()),
        dims.m,
        dims.k,
        dims.top_k,
        dims.block_m,
        routed_scaling_factor,
        static_cast<int>(blocks));
    CheckCuda(cudaGetLastError(), "alphamoe_nvfp4 down launch");
  }
  else {
    CheckCuda(cudaFuncSetAttribute(nvfp4_batch_g8_byte_up::kernel_alpha_moe_nvfp4_up_workspace_nvfp4_batch_g8_byte_up, cudaFuncAttributeMaxDynamicSharedMemorySize,
        nvfp4_batch_g8_byte_up::kGeneratedSmemTotal), "cudaFuncSetAttribute(alphamoe_nvfp4 up)");
    nvfp4_batch_g8_byte_up::kernel_alpha_moe_nvfp4_up_workspace_nvfp4_batch_g8_byte_up<<<up_grid, dim3(nvfp4_batch_g8_byte_up::kGeneratedThreads, 1, 1),
        nvfp4_batch_g8_byte_up::kGeneratedSmemTotal, stream>>>(
        hidden_states_map,
        gemm1_map,
        static_cast<uint8_t*>(hidden_states_scale.data_ptr()),
        static_cast<uint8_t*>(gemm1_weights_scale.data_ptr()),
        static_cast<float*>(output1_scale_gate_scalar.data_ptr()),
        static_cast<float*>(output1_scale_scalar.data_ptr()),
        static_cast<int*>(sorted_token_ids.data_ptr()),
        static_cast<int*>(expert_ids.data_ptr()),
        static_cast<int*>(num_tokens_post_padded.data_ptr()),
        static_cast<uint8_t*>(act_workspace.data_ptr()),
        static_cast<uint8_t*>(sf_workspace.data_ptr()),
        dims.m,
        dims.k,
        dims.top_k,
        dims.block_m);
    CheckCuda(cudaGetLastError(), "alphamoe_nvfp4 up launch");
    CheckCuda(cudaFuncSetAttribute(nvfp4_batch_g8_byte_down::kernel_alpha_moe_nvfp4_down_workspace_nvfp4_batch_g8_byte_down, cudaFuncAttributeMaxDynamicSharedMemorySize,
        nvfp4_batch_g8_byte_down::kGeneratedSmemTotal), "cudaFuncSetAttribute(alphamoe_nvfp4 down)");
    nvfp4_batch_g8_byte_down::kernel_alpha_moe_nvfp4_down_workspace_nvfp4_batch_g8_byte_down<<<down_grid, dim3(nvfp4_batch_g8_byte_down::kGeneratedThreads, 1, 1),
        nvfp4_batch_g8_byte_down::kGeneratedSmemTotal, stream>>>(
        gemm2_map,
        static_cast<uint8_t*>(gemm2_weights_scale.data_ptr()),
        static_cast<float*>(output2_scale_scalar.data_ptr()),
        static_cast<int*>(sorted_token_ids.data_ptr()),
        static_cast<int*>(expert_ids.data_ptr()),
        static_cast<int*>(num_tokens_post_padded.data_ptr()),
        static_cast<float*>(topk_weights.data_ptr()),
        static_cast<float*>(accumulator.data_ptr()),
        static_cast<uint8_t*>(act_workspace.data_ptr()),
        static_cast<uint8_t*>(sf_workspace.data_ptr()),
        dims.m,
        dims.k,
        dims.top_k,
        dims.block_m,
        routed_scaling_factor,
        static_cast<int>(blocks));
    CheckCuda(cudaGetLastError(), "alphamoe_nvfp4 down launch");
  }
}

inline void Launch(const TensorView& hidden_states, const TensorView& hidden_states_scale,
                   const TensorView& gemm1_weights, const TensorView& gemm1_weights_scale,
                   const TensorView& gemm2_weights, const TensorView& gemm2_weights_scale,
                   const TensorView& output1_scale_gate_scalar,
                   const TensorView& output1_scale_scalar, const TensorView& output2_scale_scalar,
                   const TensorView& sorted_token_ids, const TensorView& expert_ids,
                   const TensorView& num_tokens_post_padded, const TensorView& topk_weights,
                   const TensorView& accumulator, const ProblemDims& dims,
                   float routed_scaling_factor, cudaStream_t stream, const tvm::ffi::Optional<TensorView>& w1_scale_prepared, const tvm::ffi::Optional<TensorView>& w2_scale_prepared) {
  const bool packed_scale_loads =
      reinterpret_cast<uintptr_t>(hidden_states_scale.data_ptr()) % 4 == 0 &&
      reinterpret_cast<uintptr_t>(gemm1_weights_scale.data_ptr()) % 4 == 0 &&
      reinterpret_cast<uintptr_t>(gemm2_weights_scale.data_ptr()) % 4 == 0;
  const bool prepared_w1 = packed_scale_loads && HasPreparedScale(
      w1_scale_prepared, gemm1_weights_scale,
      gemm1_weights.size(0) * (dims.n / 128) * (dims.k / 256), 16);
  const bool prepared_w2 = packed_scale_loads &&
      reinterpret_cast<uintptr_t>(gemm2_weights_scale.data_ptr()) % 8 == 0 && HasPreparedScale(
          w2_scale_prepared, gemm2_weights_scale,
          gemm1_weights.size(0) * (dims.k / 128) * (dims.n / 256), 8);
  if (dims.m == 1 && dims.n == 1024 && dims.k == 6144 &&
      gemm1_weights.size(0) == 256 && dims.top_k == 8 && dims.block_m == 8) {
    LaunchFirstW2M1(hidden_states, hidden_states_scale, gemm1_weights, gemm1_weights_scale,
        gemm2_weights, gemm2_weights_scale, output1_scale_gate_scalar,
        output1_scale_scalar, output2_scale_scalar, sorted_token_ids, expert_ids,
        num_tokens_post_padded, topk_weights, accumulator, dims, routed_scaling_factor, stream);
    return;
  }
  if (dims.m == 8 && dims.n == 1024 && dims.k == 6144 && gemm1_weights.size(0) == 256 && dims.top_k == 8 && dims.block_m == 8) {
    LaunchDecodeSingletonZ2(hidden_states, hidden_states_scale, gemm1_weights, gemm1_weights_scale,
        gemm2_weights, gemm2_weights_scale, output1_scale_gate_scalar,
        output1_scale_scalar, output2_scale_scalar, sorted_token_ids, expert_ids,
        num_tokens_post_padded, topk_weights, accumulator, dims, routed_scaling_factor, stream, w1_scale_prepared, w2_scale_prepared);
  }
  else if (dims.m == 128 && dims.n == 1024 && dims.k == 6144 && gemm1_weights.size(0) == 256 && dims.top_k == 8 && dims.block_m == 8 && prepared_w1) {
    LaunchBatchPreparedG2(hidden_states, hidden_states_scale, gemm1_weights, gemm1_weights_scale,
        gemm2_weights, gemm2_weights_scale, output1_scale_gate_scalar,
        output1_scale_scalar, output2_scale_scalar, sorted_token_ids, expert_ids,
        num_tokens_post_padded, topk_weights, accumulator, dims, routed_scaling_factor, stream, w1_scale_prepared, w2_scale_prepared);
  }
  else if (dims.m == 512 && dims.n == 1024 && dims.k == 6144 && gemm1_weights.size(0) == 256 && dims.top_k == 8 && dims.block_m == 8 && prepared_w1 && prepared_w2) {
    LaunchBatchPreparedG8(hidden_states, hidden_states_scale, gemm1_weights, gemm1_weights_scale,
        gemm2_weights, gemm2_weights_scale, output1_scale_gate_scalar,
        output1_scale_scalar, output2_scale_scalar, sorted_token_ids, expert_ids,
        num_tokens_post_padded, topk_weights, accumulator, dims, routed_scaling_factor, stream, w1_scale_prepared, w2_scale_prepared);
  }
  else if (dims.m == 512 && dims.n == 1024 && dims.k == 6144 && gemm1_weights.size(0) == 256 && dims.top_k == 8 && dims.block_m == 8 && prepared_w1) {
    LaunchBatchPreparedW1G8(hidden_states, hidden_states_scale, gemm1_weights, gemm1_weights_scale,
        gemm2_weights, gemm2_weights_scale, output1_scale_gate_scalar,
        output1_scale_scalar, output2_scale_scalar, sorted_token_ids, expert_ids,
        num_tokens_post_padded, topk_weights, accumulator, dims, routed_scaling_factor, stream, w1_scale_prepared, w2_scale_prepared);
  }
  else {
    LaunchRetainedPortfolio(hidden_states, hidden_states_scale, gemm1_weights, gemm1_weights_scale,
        gemm2_weights, gemm2_weights_scale, output1_scale_gate_scalar,
        output1_scale_scalar, output2_scale_scalar, sorted_token_ids, expert_ids,
        num_tokens_post_padded, topk_weights, accumulator, dims, routed_scaling_factor, stream);
  }
}



void Run(TensorView hidden_states, TensorView hidden_states_scale, TensorView gemm1_weights,
         TensorView gemm1_weights_scale, TensorView gemm2_weights, TensorView gemm2_weights_scale,
         TensorView output1_scale_gate_scalar, TensorView output1_scale_scalar,
         TensorView output2_scale_scalar, TensorView sorted_token_ids, TensorView expert_ids,
         TensorView num_tokens_post_padded, TensorView topk_weights, TensorView out,
         TensorView accumulator, int64_t top_k, int64_t block_m, double routed_scaling_factor, tvm::ffi::Optional<TensorView> w1_scale_prepared, tvm::ffi::Optional<TensorView> w2_scale_prepared) {
  // Establish the active CUDA device before capability queries, TMA encoding,
  // function-attribute updates, stream lookup, or kernel launch.
  TVM_FFI_ICHECK(hidden_states.device().device_type == kDLCUDA)
      << "hidden_states must be a CUDA tensor";
  ffi::CUDADeviceGuard device_guard(hidden_states.device().device_id);

  const ProblemDims dims = CheckInputs(
      hidden_states, hidden_states_scale, gemm1_weights, gemm1_weights_scale, gemm2_weights,
      gemm2_weights_scale, output1_scale_gate_scalar, output1_scale_scalar, output2_scale_scalar,
      sorted_token_ids, expert_ids, num_tokens_post_padded, topk_weights, out, accumulator, top_k,
      block_m, routed_scaling_factor);
  const cudaStream_t stream = get_stream(hidden_states.device());
  Launch(hidden_states, hidden_states_scale, gemm1_weights, gemm1_weights_scale, gemm2_weights,
         gemm2_weights_scale, output1_scale_gate_scalar, output1_scale_scalar, output2_scale_scalar,
         sorted_token_ids, expert_ids, num_tokens_post_padded, topk_weights, accumulator, dims,
         static_cast<float>(routed_scaling_factor), stream, w1_scale_prepared, w2_scale_prepared);
}

}  // namespace alphamoe_nvfp4_sm100
}  // namespace flashinfer

TVM_FFI_DLL_EXPORT_TYPED_FUNC(nvfp4_aligned_moe_op, flashinfer::alphamoe_nvfp4_sm100::Run);

// Small raw-ID alignment and output-seed companion; existing compute export above is unchanged.
// Canonical alignment source SHA-256: 6aac73252726b08ce65d192583de972c0275a0432633ec3b4cc4d87a0adcf2fb
#include <math_constants.h>

// clang-format off
namespace nvfp4_small_route_alignment_seed {
#define kernel_alpha_moe_small_route_alignment_seed kernel_alpha_moe_small_route_alignment_seed_public
#define LOOM_INF CUDART_INF_F
#define NUM_MAIN_STAGES 1
#define SMEM_COUNTS_OFF 0
#define SMEM_COUNTS_STAGE_BYTES 4096
#define SMEM_COUNTS_STRIDE 4096
#define SMEM_OFFSETS_OFF 4096
#define SMEM_OFFSETS_STAGE_BYTES 4100
#define SMEM_OFFSETS_STRIDE 4100
#define SMEM_SCATTER_OFF 8196
#define SMEM_SCATTER_STAGE_BYTES 4096
#define SMEM_SCATTER_STRIDE 4096
#define SMEM_IDS_OFF 12292
#define SMEM_IDS_STAGE_BYTES 256
#define SMEM_IDS_STRIDE 256
#define SMEM_WARP_PREFIX_OFF 12548
#define SMEM_WARP_PREFIX_STAGE_BYTES 32
#define SMEM_WARP_PREFIX_STRIDE 32
#define SMEM_TOTAL_OFF 12580
#define SMEM_TOTAL_STAGE_BYTES 4
#define SMEM_TOTAL_STRIDE 4
#define SMEM_TOTAL 12672
#define THREADS 256

#include <math_constants.h>

extern "C" {

__global__ __launch_bounds__(256) void
kernel_alpha_moe_small_route_alignment_seed(int* __restrict__ topk_ids, int* __restrict__ sorted_token_ids, int* __restrict__ expert_ids, int* __restrict__ num_tokens_post_padded, int* __restrict__ cumsum_buffer, __nv_bfloat16* __restrict__ initial_out, float* __restrict__ seeded_accumulator, int num_experts, int block_size, int num_pairs, int sorted_capacity, long long output_numel)
{
    const int tid = threadIdx.x;
    const uint32_t warp = __shfl_sync(0xffffffff, threadIdx.x / 32, 0);
    uint32_t lane;
    asm("mov.u32 %0, %%laneid;" : "=r"(lane));

    extern __shared__ __align__(1024) char smem_raw[];
    int smem;
    smem = (int)(unsigned long long)__cvta_generic_to_shared(smem_raw);

    const int bid = blockIdx.x;
    const int num_bids = gridDim.x;

    // Kernel setup ops
    int* counts = reinterpret_cast<int*>(smem_raw + 0);
    const int counts_addr = smem + 0;
    int* offsets = reinterpret_cast<int*>(smem_raw + 4096);
    const int offsets_addr = smem + 4096;
    int* scatter = reinterpret_cast<int*>(smem_raw + 8196);
    const int scatter_addr = smem + 8196;
    int* ids = reinterpret_cast<int*>(smem_raw + 12292);
    const int ids_addr = smem + 12292;
    int* warp_prefix = reinterpret_cast<int*>(smem_raw + 12548);
    const int warp_prefix_addr = smem + 12548;
    int* total = reinterpret_cast<int*>(smem_raw + 12580);
    const int total_addr = smem + 12580;

    // === Task calls (dependency order) ===
    if (blockIdx.x == 0) {
        for (int bin_zero = tid; bin_zero < num_experts; bin_zero += 256) {
            counts[bin_zero] = 0;
            scatter[bin_zero] = 0;
        }
        for (int pad = tid; pad < sorted_capacity; pad += 256) {
            sorted_token_ids[pad] = num_pairs;
        }
        __syncthreads();
        for (int pair_load = tid; pair_load < num_pairs; pair_load += 256) {
            int pair_bin = topk_ids[pair_load] + 1;
            ids[pair_load] = pair_bin;
            atomicAdd(&counts[pair_bin], 1);
        }
        __syncthreads();
        int padded[4];
        int thread_total = 0;
        #pragma unroll
        for (int slot = 0; slot < 4; slot++) {
            int bin_scan = tid * 4 + slot;
            int padded_count = 0;
            if (bin_scan < num_experts) {
                int count = counts[bin_scan];
                if (block_size == 8) {
                    padded_count = count + 7 & -8;
                } else {
                    padded_count = count + 15 & -16;
                }
            }
            padded[slot] = padded_count;
            thread_total = thread_total + padded_count;
        }
        int inclusive = thread_total;
        int _shfl_up_0 = __shfl_up_sync(0xFFFFFFFF, inclusive, 1, 32);
        int peer = _shfl_up_0;
        if (lane >= 1) {
            inclusive = inclusive + peer;
        }
        int _shfl_up_1 = __shfl_up_sync(0xFFFFFFFF, inclusive, 2, 32);
        int peer_0 = _shfl_up_1;
        if (lane >= 2) {
            inclusive = inclusive + peer_0;
        }
        int _shfl_up_2 = __shfl_up_sync(0xFFFFFFFF, inclusive, 4, 32);
        int peer_1 = _shfl_up_2;
        if (lane >= 4) {
            inclusive = inclusive + peer_1;
        }
        int _shfl_up_3 = __shfl_up_sync(0xFFFFFFFF, inclusive, 8, 32);
        int peer_2 = _shfl_up_3;
        if (lane >= 8) {
            inclusive = inclusive + peer_2;
        }
        int _shfl_up_4 = __shfl_up_sync(0xFFFFFFFF, inclusive, 16, 32);
        int peer_3 = _shfl_up_4;
        if (lane >= 16) {
            inclusive = inclusive + peer_3;
        }
        if (lane == 31) {
            warp_prefix[warp] = inclusive;
        }
        __syncthreads();
        if (warp == 0) {
            int warp_total = 0;
            if (lane < 8) {
                warp_total = warp_prefix[lane];
            }
            int warp_inclusive = warp_total;
            int _shfl_up_5 = __shfl_up_sync(0xFFFFFFFF, warp_inclusive, 1, 32);
            int warp_peer = _shfl_up_5;
            if (lane >= 1) {
                warp_inclusive = warp_inclusive + warp_peer;
            }
            int _shfl_up_6 = __shfl_up_sync(0xFFFFFFFF, warp_inclusive, 2, 32);
            int warp_peer_0 = _shfl_up_6;
            if (lane >= 2) {
                warp_inclusive = warp_inclusive + warp_peer_0;
            }
            int _shfl_up_7 = __shfl_up_sync(0xFFFFFFFF, warp_inclusive, 4, 32);
            int warp_peer_1 = _shfl_up_7;
            if (lane >= 4) {
                warp_inclusive = warp_inclusive + warp_peer_1;
            }
            if (lane < 8) {
                warp_prefix[lane] = warp_inclusive - warp_total;
            }
            if (lane == 7) {
                total[0] = warp_inclusive;
            }
        }
        __syncthreads();
        int prefix = warp_prefix[warp] + inclusive - thread_total;
        #pragma unroll
        for (int publish_slot = 0; publish_slot < 4; publish_slot++) {
            int publish_bin = tid * 4 + publish_slot;
            if (publish_bin < num_experts) {
                offsets[publish_bin] = prefix;
            }
            prefix = prefix + padded[publish_slot];
        }
        if (tid == 0) {
            offsets[num_experts] = total[0];
        }
        __syncthreads();
        for (int pair = tid; pair < num_pairs; pair += 256) {
            int bin_scatter = ids[pair];
            int _atomic_old_0 = atomicAdd(&scatter[bin_scatter], 1);
            int local_row = _atomic_old_0;
            int destination = offsets[bin_scatter] + local_row;
            sorted_token_ids[destination] = pair;
            if (block_size == 8) {
                if ((local_row & 7) == 0) {
                    expert_ids[destination >> 3] = bin_scatter - 1;
                }
            } else if ((local_row & 15) == 0) {
                expert_ids[destination >> 4] = bin_scatter - 1;
            }
        }
        __syncthreads();
        for (int workspace_bin = tid; workspace_bin < num_experts; workspace_bin += 256) {
            cumsum_buffer[workspace_bin] = offsets[workspace_bin] + scatter[workspace_bin];
        }
        if (tid == 0) {
            cumsum_buffer[num_experts] = total[0];
            num_tokens_post_padded[0] = total[0];
        }
    } else {
        long long seed_start = ((long long)blockIdx.x - 1) * 256 + (long long)tid;
        long long seed_stride = ((long long)gridDim.x - 1) * 256;
        #pragma unroll 1
        for (long long seed_index = seed_start; seed_index < output_numel; seed_index += seed_stride) {
            float seed_value = (float)initial_out[seed_index];
            *(reinterpret_cast<float*>(seeded_accumulator + seed_index) + (0)) = seed_value;
        }
    }
}

} // extern "C"


constexpr int kAlignmentThreads = THREADS;
constexpr int kAlignmentSmemTotal = SMEM_TOTAL;
#undef LOOM_INF
#undef NUM_MAIN_STAGES
#undef SMEM_COUNTS_OFF
#undef SMEM_COUNTS_STAGE_BYTES
#undef SMEM_COUNTS_STRIDE
#undef SMEM_OFFSETS_OFF
#undef SMEM_OFFSETS_STAGE_BYTES
#undef SMEM_OFFSETS_STRIDE
#undef SMEM_SCATTER_OFF
#undef SMEM_SCATTER_STAGE_BYTES
#undef SMEM_SCATTER_STRIDE
#undef SMEM_IDS_OFF
#undef SMEM_IDS_STAGE_BYTES
#undef SMEM_IDS_STRIDE
#undef SMEM_WARP_PREFIX_OFF
#undef SMEM_WARP_PREFIX_STAGE_BYTES
#undef SMEM_WARP_PREFIX_STRIDE
#undef SMEM_TOTAL_OFF
#undef SMEM_TOTAL_STAGE_BYTES
#undef SMEM_TOTAL_STRIDE
#undef SMEM_TOTAL
#undef THREADS
#undef kernel_alpha_moe_small_route_alignment_seed
}  // namespace nvfp4_small_route_alignment_seed
// clang-format on

namespace flashinfer {
namespace alphamoe_nvfp4_sm100 {

void AlignAndSeedOutput(TensorView topk_ids, int64_t num_experts, int64_t block_size,
                    TensorView sorted_token_ids, TensorView expert_ids,
                    TensorView num_tokens_post_padded, TensorView cumsum_buffer,
                    TensorView initial_out, TensorView seeded_accumulator,
                    bool pad_sorted_token_ids) {
  TVM_FFI_ICHECK(topk_ids.device().device_type == kDLCUDA)
      << "topk_ids must be a CUDA tensor";
  ffi::CUDADeviceGuard device_guard(topk_ids.device().device_id);
  CheckSm100OrSm103(topk_ids.device().device_id);
  CheckTensor(topk_ids, dl_int32, 2, true, "topk_ids", "int32");
  CheckTensor(sorted_token_ids, dl_int32, 1, true, "sorted_token_ids", "int32");
  CheckTensor(expert_ids, dl_int32, 1, true, "expert_ids", "int32");
  CheckTensor(num_tokens_post_padded, dl_int32, 1, true, "num_tokens_post_padded", "int32");
  CheckTensor(cumsum_buffer, dl_int32, 1, true, "cumsum_buffer", "int32");
  CheckTensor(initial_out, dl_bfloat16, 2, true, "initial_out", "bfloat16");
  CheckTensor(seeded_accumulator, dl_float32, 2, true, "seeded_accumulator", "float32");
  const int device_id = topk_ids.device().device_id;
  CheckSameDevice(initial_out, device_id, "initial_out");
  CheckSameDevice(seeded_accumulator, device_id, "seeded_accumulator");
  TVM_FFI_ICHECK(initial_out.size(0) == topk_ids.size(0) && initial_out.size(1) > 0)
      << "initial_out must have the route row count and a positive output width";
  CheckShape2(seeded_accumulator, initial_out.size(0), initial_out.size(1),
              "seeded_accumulator");
  CheckNoOverlap(seeded_accumulator, initial_out, "initial_out", "seeded_accumulator");
  CheckSameDevice(sorted_token_ids, device_id, "sorted_token_ids");
  CheckSameDevice(expert_ids, device_id, "expert_ids");
  CheckSameDevice(num_tokens_post_padded, device_id, "num_tokens_post_padded");
  CheckSameDevice(cumsum_buffer, device_id, "cumsum_buffer");
  TVM_FFI_ICHECK((topk_ids.size(0) == 1 || topk_ids.size(0) == 8) && topk_ids.size(1) == 8)
      << "topk_ids must have shape (1, 8) or (8, 8)";
  TVM_FFI_ICHECK(num_experts == 257 || num_experts == 513)
      << "num_experts must include the reserved bin and equal 257 or 513";
  TVM_FFI_ICHECK(block_size == 8 || block_size == 16) << "block_size must be 8 or 16";
  TVM_FFI_ICHECK(pad_sorted_token_ids) << "full-capacity sorted-token padding is required";
  const int64_t pairs = topk_ids.numel();
  TVM_FFI_ICHECK(sorted_token_ids.numel() >= pairs * block_size &&
                 sorted_token_ids.numel() <= kIntMax)
      << "sorted_token_ids must cover every padded route and fit int32";
  TVM_FFI_ICHECK(expert_ids.numel() >= pairs)
      << "expert_ids must cover every possible used block";
  TVM_FFI_ICHECK(num_tokens_post_padded.numel() == 1)
      << "num_tokens_post_padded must have one entry";
  TVM_FFI_ICHECK(cumsum_buffer.numel() >= num_experts + 1)
      << "cumsum_buffer must cover all bins and the final extent";
  CheckNoOverlap(initial_out, topk_ids, "topk_ids", "initial_out");
  CheckNoOverlap(initial_out, sorted_token_ids, "sorted_token_ids", "initial_out");
  CheckNoOverlap(initial_out, expert_ids, "expert_ids", "initial_out");
  CheckNoOverlap(initial_out, num_tokens_post_padded, "num_tokens_post_padded", "initial_out");
  CheckNoOverlap(initial_out, cumsum_buffer, "cumsum_buffer", "initial_out");
  CheckNoOverlap(seeded_accumulator, topk_ids, "topk_ids", "seeded_accumulator");
  CheckNoOverlap(seeded_accumulator, sorted_token_ids, "sorted_token_ids", "seeded_accumulator");
  CheckNoOverlap(seeded_accumulator, expert_ids, "expert_ids", "seeded_accumulator");
  CheckNoOverlap(seeded_accumulator, num_tokens_post_padded, "num_tokens_post_padded", "seeded_accumulator");
  CheckNoOverlap(seeded_accumulator, cumsum_buffer, "cumsum_buffer", "seeded_accumulator");
  const cudaStream_t stream = get_stream(topk_ids.device());
  const int64_t output_numel = initial_out.numel();
  const unsigned int seed_ctas = static_cast<unsigned int>((output_numel + 1023) / 1024);
  nvfp4_small_route_alignment_seed::kernel_alpha_moe_small_route_alignment_seed_public<<<
      dim3(seed_ctas + 1, 1, 1), dim3(nvfp4_small_route_alignment_seed::kAlignmentThreads, 1, 1),
      nvfp4_small_route_alignment_seed::kAlignmentSmemTotal, stream>>>(
          static_cast<int*>(topk_ids.data_ptr()),
          static_cast<int*>(sorted_token_ids.data_ptr()),
          static_cast<int*>(expert_ids.data_ptr()),
          static_cast<int*>(num_tokens_post_padded.data_ptr()),
          static_cast<int*>(cumsum_buffer.data_ptr()),
          static_cast<__nv_bfloat16*>(initial_out.data_ptr()),
          static_cast<float*>(seeded_accumulator.data_ptr()),
          static_cast<int>(num_experts), static_cast<int>(block_size),
          static_cast<int>(pairs), static_cast<int>(sorted_token_ids.numel()),
          static_cast<long long>(output_numel));
  CheckCuda(cudaGetLastError(), "alphamoe_nvfp4_align_and_seed_output kernel launch");
}

void RunRoutedSeeded(
    TensorView hidden_states, TensorView hidden_states_scale, TensorView gemm1_weights,
    TensorView gemm1_weights_scale, TensorView gemm2_weights, TensorView gemm2_weights_scale,
    TensorView output1_scale_gate_scalar, TensorView output1_scale_scalar,
    TensorView output2_scale_scalar, TensorView sorted_token_ids, TensorView expert_ids,
    TensorView num_tokens_post_padded, TensorView topk_weights, TensorView out,
    TensorView accumulator, TensorView topk_ids, TensorView cumsum_buffer,
    int64_t top_k, int64_t block_m, double routed_scaling_factor, tvm::ffi::Optional<TensorView> w1_scale_prepared, tvm::ffi::Optional<TensorView> w2_scale_prepared) {
  TVM_FFI_ICHECK(hidden_states.device().device_type == kDLCUDA)
      << "hidden_states must be a CUDA tensor";
  ffi::CUDADeviceGuard device_guard(hidden_states.device().device_id);
  // Preserve all existing aligned host checks before the first GPU launch.
  (void)CheckInputs(
      hidden_states, hidden_states_scale, gemm1_weights, gemm1_weights_scale, gemm2_weights,
      gemm2_weights_scale, output1_scale_gate_scalar, output1_scale_scalar, output2_scale_scalar,
      sorted_token_ids, expert_ids, num_tokens_post_padded, topk_weights, out, accumulator,
      top_k, block_m, routed_scaling_factor);
  CheckTensor(topk_ids, dl_int32, 2, true, "topk_ids", "int32");
  CheckSameDevice(topk_ids, hidden_states.device().device_id, "topk_ids");
  CheckShape2(topk_ids, hidden_states.size(0), top_k, "topk_ids");
  AlignAndSeedOutput(topk_ids, gemm1_weights.size(0) + 1, block_m,
                     sorted_token_ids, expert_ids, num_tokens_post_padded, cumsum_buffer,
                     out, accumulator, true);
  // Run is the unchanged implementation of nvfp4_aligned_moe_op. It consumes
  // exactly the accumulator initialized by the preceding same-stream launch.
  Run(hidden_states, hidden_states_scale, gemm1_weights, gemm1_weights_scale, gemm2_weights,
      gemm2_weights_scale, output1_scale_gate_scalar, output1_scale_scalar, output2_scale_scalar,
      sorted_token_ids, expert_ids, num_tokens_post_padded, topk_weights, out, accumulator,
      top_k, block_m, routed_scaling_factor, w1_scale_prepared, w2_scale_prepared);
}

