extern "C" {

__global__ __launch_bounds__(192, 1) void
kernel_alpha_moe_nvfp4_up_workspace(const __grid_constant__ CUtensorMap x, const __grid_constant__ CUtensorMap W1, uint8_t* __restrict__ x_scale, const __grid_constant__ CUtensorMap w1_scale_prepared, float* __restrict__ output1_scale_gate_scalar, float* __restrict__ output1_scale_scalar, int* __restrict__ sorted_token_ids, int* __restrict__ expert_ids, int* __restrict__ num_tokens_post_padded, uint8_t* __restrict__ act_workspace, uint8_t* __restrict__ sf_workspace, int M, int K, int top_k, int route_block_m)
{
    const int tid = threadIdx.x;
    const uint32_t warp = __shfl_sync(0xffffffff, threadIdx.x / 32, 0);
    uint32_t lane;
    asm("mov.u32 %0, %%laneid;" : "=r"(lane));

    extern __shared__ __align__(1024) char smem_raw[];
    int smem;
    smem = (int)(unsigned long long)__cvta_generic_to_shared(smem_raw);

    const int mbar_base = smem;
    #define up_full_addr (mbar_base + 0)
    #define up_free_addr (mbar_base + 16)
    #define up_ready_addr (mbar_base + 32)

    const int bid = blockIdx.x;
    const int num_bids = gridDim.x;

    // Kernel setup ops
    uint8_t* smem_w1 = reinterpret_cast<uint8_t*>(smem_raw + 1024);
    const int smem_w1_addr = smem + 1024;
    uint8_t* smem_x = reinterpret_cast<uint8_t*>(smem_raw + 33792);
    const int smem_x_addr = smem + 33792;
    uint8_t* smem_w1_gate_sf = reinterpret_cast<uint8_t*>(smem_raw + 35840);
    const int smem_w1_gate_sf_addr = smem + 35840;
    uint8_t* smem_w1_up_sf = reinterpret_cast<uint8_t*>(smem_raw + 37888);
    const int smem_w1_up_sf_addr = smem + 37888;
    uint8_t* smem_x_sf = reinterpret_cast<uint8_t*>(smem_raw + 39936);
    const int smem_x_sf_addr = smem + 39936;
    float* smem_act_scale = reinterpret_cast<float*>(smem_raw + 38912);
    const int smem_act_scale_addr = smem + 38912;

    // Mbarrier init (3 pipeline groups, 0 ordered-sequence groups, 5 barriers)
    // Mbarriers at smem_raw[0..40)

    if (warp == 0) {
        uint32_t leader = elect_sync();
        if (leader) {
            // --- pipeline 'up_pipe' ---
            // up_full: 2 barriers, init_count=2
            mbarrier_init(smem + 0, 2);
            mbarrier_init(smem + 8, 2);
            // up_free: 2 barriers, init_count=1
            mbarrier_init(smem + 16, 1);
            mbarrier_init(smem + 24, 1);
            // --- pipeline 'single_pipe' ---
            // up_ready: 1 barriers, init_count=1
            mbarrier_init(smem + 32, 1);
            asm volatile("fence.mbarrier_init.release.cluster;" ::: "memory");
        }
    }

    __syncwarp();

    // TMEM alloc (128 columns, 80 used)
    volatile int* tmem_addr_storage = (volatile int*)(smem_raw + 40);
    if (warp == 0) {
        int _tmem_hold = smem + 40;
        asm volatile("tcgen05.alloc.cta_group::1.sync.aligned.shared::cta.b32 [%0], %1;" :: "r"(_tmem_hold), "r"(128) : "memory");
        __syncwarp();
        asm volatile("tcgen05.relinquish_alloc_permit.cta_group::1.sync.aligned;");
    }

    __syncthreads();
    asm volatile("tcgen05.fence::after_thread_sync;");

    const int taddr = tmem_addr_storage[0];

    // Kernel post-init ops
    const int tmem_up_acc = taddr;
    const int tmem_up_gate_sf = taddr + 32;
    const int tmem_up_up_sf = taddr + 48;
    const int tmem_up_x_sf = taddr + 64;

    // ---- Role: load ----
    if (warp == 0) {
        { // load_main
            int route_base_l = blockIdx.x * 8;
            int route_extent_l = num_tokens_post_padded[0];
            bool owns_route_l = route_base_l < route_extent_l;
            bool pair_upper_l = 0;
            int route_expert_l = 0;
            if (owns_route_l) {
                int current_route_block_l = route_base_l / route_block_m;
                route_expert_l = expert_ids[current_route_block_l];
                int subtiles_per_block_l = route_block_m / 8;
                int pair_position_l = blockIdx.x;
                if (subtiles_per_block_l % 2 != 0) {
                    int run_first_block_l = current_route_block_l;
                    #pragma unroll 1
                    for (int run_chunk_l = 0; run_chunk_l < (current_route_block_l + 32) / 32; run_chunk_l++) {
                        int probe_block_l = (unsigned int)(current_route_block_l - 1 - run_chunk_l * 32) - lane;
                        bool at_boundary_l = 1;
                        if (probe_block_l >= 0) {
                            int probe_expert_l = expert_ids[probe_block_l];
                            at_boundary_l = probe_expert_l != route_expert_l;
                        }
                        unsigned int _vote_0 = __ballot_sync(0xFFFFFFFF, at_boundary_l);
                        unsigned int boundary_mask_l = _vote_0;
                        if (boundary_mask_l != 0) {
                            int _ffs_0 = __ffs(boundary_mask_l);
                            int first_boundary_lane_l = _ffs_0 - 1;
                            run_first_block_l = current_route_block_l - run_chunk_l * 32 - first_boundary_lane_l;
                            break;
                        }
                    }
                    pair_position_l = blockIdx.x - run_first_block_l * subtiles_per_block_l;
                }
                if (pair_position_l % 2 == 0) {
                    if (route_extent_l > route_base_l + 8) {
                        int next_expert_l = expert_ids[(route_base_l + 8) / route_block_m];
                        pair_upper_l = next_expert_l == route_expert_l;
                    }
                } else {
                    owns_route_l = 0;
                }
            }
            unsigned int _phase_up_free = 1;
            if (owns_route_l) {
                int intermediate_block = blockIdx.y;
                int intermediate_blocks = gridDim.y;
                int expert = route_expert_l;
                int lane_pair_up = sorted_token_ids[(unsigned int)route_base_l + lane / 4];
                int lane_pair_up_hi = M * top_k;
                if (pair_upper_l) {
                    lane_pair_up_hi = sorted_token_ids[(unsigned int)(route_base_l + 8) + lane / 4];
                }
                int _min_0 = ((lane_pair_up / top_k) < (M - 1) ? (lane_pair_up / top_k) : (M - 1));
                int lane_token_up = _min_0;
                int _min_1 = ((lane_pair_up_hi / top_k) < (M - 1) ? (lane_pair_up_hi / top_k) : (M - 1));
                int lane_token_up_hi = _min_1;
                int _shfl_0 = __shfl_sync(0xFFFFFFFF, lane_token_up, 0);
                int row0 = _shfl_0;
                int _shfl_1 = __shfl_sync(0xFFFFFFFF, lane_token_up, 4);
                int row1 = _shfl_1;
                int _shfl_2 = __shfl_sync(0xFFFFFFFF, lane_token_up, 8);
                int row2 = _shfl_2;
                int _shfl_3 = __shfl_sync(0xFFFFFFFF, lane_token_up, 12);
                int row3 = _shfl_3;
                int _shfl_4 = __shfl_sync(0xFFFFFFFF, lane_token_up, 16);
                int row4 = _shfl_4;
                int _shfl_5 = __shfl_sync(0xFFFFFFFF, lane_token_up, 20);
                int row5 = _shfl_5;
                int _shfl_6 = __shfl_sync(0xFFFFFFFF, lane_token_up, 24);
                int row6 = _shfl_6;
                int _shfl_7 = __shfl_sync(0xFFFFFFFF, lane_token_up, 28);
                int row7 = _shfl_7;
                int _shfl_8 = __shfl_sync(0xFFFFFFFF, lane_token_up_hi, 0);
                int row8 = _shfl_8;
                int _shfl_9 = __shfl_sync(0xFFFFFFFF, lane_token_up_hi, 4);
                int row9 = _shfl_9;
                int _shfl_10 = __shfl_sync(0xFFFFFFFF, lane_token_up_hi, 8);
                int row10 = _shfl_10;
                int _shfl_11 = __shfl_sync(0xFFFFFFFF, lane_token_up_hi, 12);
                int row11 = _shfl_11;
                int _shfl_12 = __shfl_sync(0xFFFFFFFF, lane_token_up_hi, 16);
                int row12 = _shfl_12;
                int _shfl_13 = __shfl_sync(0xFFFFFFFF, lane_token_up_hi, 20);
                int row13 = _shfl_13;
                int _shfl_14 = __shfl_sync(0xFFFFFFFF, lane_token_up_hi, 24);
                int row14 = _shfl_14;
                int _shfl_15 = __shfl_sync(0xFFFFFFFF, lane_token_up_hi, 28);
