            int warp_peer_2 = _shfl_up_14;
            int _shfl_up_15 = __shfl_up_sync(0xFFFFFFFF, owner_warp_inclusive, 4, 32);
            int owner_warp_peer_3 = _shfl_up_15;
            if (lane >= 4) {
