        static_cast<int*>(num_tokens_post_padded.data_ptr()),
        static_cast<float*>(topk_weights.data_ptr()),
        static_cast<float*>(accumulator.data_ptr()),
        static_cast<uint8_t*>(act_workspace.data_ptr()),
        static_cast<uint8_t*>(sf_workspace.data_ptr()),
        dims.m,
        dims.k,
