        SeedWorkspacePtr(initial_out),
        static_cast<__nv_bfloat16*>(out.data_ptr()),
        dims.m,
        dims.k,
        dims.top_k,
        static_cast<float>(routed_scaling_factor));
    CheckCuda(cudaGetLastError(), "complete finalize launch");
  }
    return;
  }
}
